 * DUAL_PARTITION 双分区试启动发布（任务经 PENDING/TRIAL/COMMITTED/ROLLED_BACK 流转）。
 */
public enum ReleaseKind {
    NORMAL,
    DUAL_PARTITION
}

package com.example.starter.firmware.domain;

/**
 * 双分区试启动任务状态：PENDING 待试启动；TRIAL 试启动中（未切换版本）；
 * COMMITTED 健康确认通过并已切换版本与分区（终态）；ROLLED_BACK 已回滚（终态）；CANCELLED 已取消（终态）。
 */
public enum BootTaskStatus {
    PENDING,
    TRIAL,
    COMMITTED,
    ROLLED_BACK,
    CANCELLED
}

package com.example.starter.firmware.domain;

/**
 * 双分区回执阶段：TRIAL_BOOT 试启动回执（进入 TRIAL，不切换版本）；
 * HEALTH_CONFIRM 健康确认回执（60 秒窗口内才 COMMITTED 并正式切换）。
 * 固件下载成功不代表启动健康，SUCCESS 回执必须携带阶段以区分试启动与正式切换。
 */
public enum BootReceiptPhase {
    TRIAL_BOOT,
    HEALTH_CONFIRM
}

