        if (request.phase() == BootReceiptPhase.TRIAL_BOOT) {
            // 同任务试启动字段不可改：同字段重报返回冻结的 TRIAL 阶段视图，异字段 409
            if (task.targetPartition().equals(request.targetPartition())
